/* ============================================================
   APEX GRAND PRIX RACING LEAGUE DATABASE
   Full dataset - 30,000 rows across 5 tables
   ============================================================ */
use projects;
CREATE TABLE Teams (
    team_id INT PRIMARY KEY,
    team_name VARCHAR(50) NOT NULL UNIQUE,
    base_country VARCHAR(50) NOT NULL,
    founded_year INT CHECK (founded_year >= 1950),
    championships_won INT DEFAULT 0 CHECK (championships_won >= 0)
);


CREATE TABLE Drivers (
    driver_id INT PRIMARY KEY,
    driver_name VARCHAR(60) NOT NULL,
    nationality VARCHAR(30) NOT NULL,
    car_number INT UNIQUE CHECK (car_number BETWEEN 1 AND 99),
    team_id INT,
    date_of_birth DATE,
    FOREIGN KEY (team_id) REFERENCES Teams(team_id)
);


CREATE TABLE Circuits (
    circuit_id INT PRIMARY KEY,
    circuit_name VARCHAR(60) NOT NULL UNIQUE,
    country VARCHAR(50) NOT NULL,
    length_km DECIMAL(6,3) CHECK (length_km > 0),
    total_laps INT CHECK (total_laps > 0)
);


CREATE TABLE Races (
    race_id INT PRIMARY KEY,
    circuit_id INT,
    season_year INT CHECK (season_year >= 2000),
    race_date DATE NOT NULL,
    race_name VARCHAR(60) NOT NULL,
    FOREIGN KEY (circuit_id) REFERENCES Circuits(circuit_id)
);


CREATE TABLE LapTimes (
    lap_id INT PRIMARY KEY,
    race_id INT,
    driver_id INT,
    lap_number INT CHECK (lap_number > 0),
    lap_time_seconds DECIMAL(6,3) CHECK (lap_time_seconds > 0),
    position INT CHECK (position BETWEEN 1 AND 24),
    pit_stop VARCHAR(3) DEFAULT 'No' CHECK (pit_stop IN ('Yes','No')),
    FOREIGN KEY (race_id) REFERENCES Races(race_id),
    FOREIGN KEY (driver_id) REFERENCES Drivers(driver_id)
);






































